-- Attach existing API/mobile permissions to their business pages without changing grants or client boundaries.
INSERT INTO sys_menu(id,code,name,type,parent_id,permission_code,grantable,sort_order,status,version) SELECT 1874300000000040001,'CLASS_READ','班级管理 · 查询班级','BUTTON',page.id,'CLASS_READ',1,5000,'ENABLED',1 FROM sys_menu page WHERE page.type='PAGE' AND page.route='/organizations' AND NOT EXISTS(SELECT 1 FROM sys_menu existing WHERE existing.code='CLASS_READ');
UPDATE sys_permission target JOIN sys_menu page ON page.type='PAGE' AND page.route='/organizations' LEFT JOIN sys_permission parent_permission ON parent_permission.permission_code=page.permission_code SET target.permission_name='班级管理 · 查询班级',target.parent_id=parent_permission.id WHERE target.permission_code='CLASS_READ';
